Write {"file_path":"D:\code\ESI.ts\tests\bdd\step-definitions\core\market.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/market.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-market-client',
      baseUrl: 'https://esi.evetech.net',
      timeout: 5000,
    });
  });

  test('WHEN getMarketPrices is called, the client shall return price data for all tradeable items', ({ given, when, then }) => {
    let result: any;

    given('the ESI market endpoint is available', () => {
      const expectedPrices = [
        TestDataFactory.createMarketPrice({
          type_id: 34,
          average_price: 5000000.0,
          adjusted_price: 5100000.0,
        }),
        TestDataFactory.createMarketPrice({
          type_id: 35,
          average_price: 15000000.0,
          adjusted_price: 15200000.0,
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketPrices')
        .mockResolvedValue(expectedPrices);
    });

    when('getMarketPrices is called', async () => {
      result = await client.market.getMarketPrices();
    });

    then('the client shall return an array of market prices with type_id, average_price, and adjusted_price', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result.length).toBeGreaterThan(0);
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('average_price');
      expect(result[0]).toHaveProperty('adjusted_price');
      expect(typeof result[0].average_price).toBe('number');
      expect(result[0].average_price).toBeGreaterThan(0);
    });
  });

  test('IF market data is unavailable, THEN the client shall throw an EsiError with status 503', ({ given, when, then }) => {
    let caughtError: any;

    given('the ESI market endpoint returns a 503 Service Unavailable error', () => {
      const serviceError = TestDataFactory.createError(503);

      jest
        .spyOn(client.market, 'getMarketPrices')
        .mockRejectedValue(serviceError);
    });

    when('getMarketPrices is called and the service is unavailable', async () => {
      try {
        await client.market.getMarketPrices();
      } catch (error) {
        caughtError = error;
      }
    });

    then('the client shall throw an EsiError with status 503', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN getMarketOrders is called with a region ID, the client shall return buy and sell orders', ({ given, when, then }) => {
    const regionId = 10000002;
    const typeId = 34;
    let result: any;

    given('the ESI market orders endpoint is available for a valid region', () => {
      const expectedOrders = [
        TestDataFactory.createMarketOrder({
          order_id: 5000000001,
          type_id: typeId,
          location_id: 60003760,
          volume_total: 1000000,
          volume_remain: 500000,
          min_volume: 1,
          price: 4.5,
          is_buy_order: true,
          duration: 90,
          issued: '2024-01-15T12:00:00Z',
          range: 'region',
        }),
        TestDataFactory.createMarketOrder({
          order_id: 5000000002,
          type_id: typeId,
          location_id: 60003760,
          volume_total: 2000000,
          volume_remain: 2000000,
          min_volume: 1,
          price: 4.6,
          is_buy_order: false,
          duration: 30,
          issued: '2024-01-15T10:00:00Z',
          range: 'station',
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketOrders')
        .mockResolvedValue(expectedOrders);
    });

    when('getMarketOrders is called with region ID 10000002', async () => {
      result = await client.market.getMarketOrders(regionId);
    });

    then('the client shall return an array of orders each containing order_id, type_id, price, and is_buy_order', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result.length).toBe(2);
      expect(result[0]).toHaveProperty('order_id');
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('price');
      expect(result[0]).toHaveProperty('is_buy_order');
      expect(result[0].type_id).toBe(typeId);
      expect(typeof result[0].is_buy_order).toBe('boolean');
    });
  });

  test('WHEN market orders are retrieved, the client shall distinguish between buy and sell orders', ({ given, when, then }) => {
    const regionId = 10000002;
    let buyOrders: any;
    let sellOrders: any;

    given('the ESI market orders endpoint returns mixed buy and sell orders', () => {
      const mixedOrders = [
        TestDataFactory.createMarketOrder({
          order_id: 1,
          is_buy_order: true,
          price: 4.5,
        }),
        TestDataFactory.createMarketOrder({
          order_id: 2,
          is_buy_order: false,
          price: 4.6,
        }),
        TestDataFactory.createMarketOrder({
          order_id: 3,
          is_buy_order: true,
          price: 4.45,
        }),
        TestDataFactory.createMarketOrder({
          order_id: 4,
          is_buy_order: false,
          price: 4.65,
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketOrders')
        .mockResolvedValue(mixedOrders);
    });

    when('getMarketOrders is called and the results are filtered by is_buy_order', async () => {
      const result = await client.market.getMarketOrders(regionId);
      buyOrders = result.filter((order: any) => order.is_buy_order);
      sellOrders = result.filter((order: any) => !order.is_buy_order);
    });

    then('the client shall separate orders into buy orders and sell orders with correct counts', () => {
      expect(buyOrders.length).toBe(2);
      expect(sellOrders.length).toBe(2);
      expect(buyOrders.every((order: any) => order.is_buy_order)).toBe(true);
      expect(sellOrders.every((order: any) => !order.is_buy_order)).toBe(true);

      // Buy orders should have lower prices (buyers want to pay less)
      expect(buyOrders[0].price).toBeLessThan(sellOrders[0].price);
    });
  });

  test('WHEN getMarketHistory is called, the client shall return historical price and volume data', ({ given, when, then }) => {
    const regionId = 10000002;
    const typeId = 34;
    let result: any;

    given('the ESI market history endpoint is available for a valid region and type', () => {
      const expectedHistory = [
        TestDataFactory.createMarketHistory({
          date: '2024-01-15',
          volume: 1000000000,
          order_count: 2500,
          lowest: 4.2,
          highest: 4.8,
          average: 4.5,
        }),
        TestDataFactory.createMarketHistory({
          date: '2024-01-14',
          volume: 950000000,
          order_count: 2400,
          lowest: 4.15,
          highest: 4.75,
          average: 4.45,
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketHistory')
        .mockResolvedValue(expectedHistory);
    });

    when('getMarketHistory is called with region ID 10000002 and type ID 34', async () => {
      result = await client.market.getMarketHistory(regionId, typeId);
    });

    then('the client shall return an array of history entries with date, volume, order_count, lowest, highest, and average', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result.length).toBeGreaterThan(0);
      expect(result[0]).toHaveProperty('date');
      expect(result[0]).toHaveProperty('volume');
      expect(result[0]).toHaveProperty('order_count');
      expect(result[0]).toHaveProperty('lowest');
      expect(result[0]).toHaveProperty('highest');
      expect(result[0]).toHaveProperty('average');
      expect(result[0].highest).toBeGreaterThanOrEqual(result[0].lowest);
    });
  });

  test('WHEN historical market data is retrieved, the client shall enable price trend analysis', ({ given, when, then }) => {
    const regionId = 10000002;
    const typeId = 34;
    let result: any;
    let priceChanges: any;

    given('the ESI market history endpoint returns data with a consistent upward price trend', () => {
      const trendingHistory = [
        TestDataFactory.createMarketHistory({
          date: '2024-01-10',
          average: 4.0,
        }),
        TestDataFactory.createMarketHistory({
          date: '2024-01-11',
          average: 4.1,
        }),
        TestDataFactory.createMarketHistory({
          date: '2024-01-12',
          average: 4.2,
        }),
        TestDataFactory.createMarketHistory({
          date: '2024-01-13',
          average: 4.3,
        }),
        TestDataFactory.createMarketHistory({
          date: '2024-01-14',
          average: 4.4,
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketHistory')
        .mockResolvedValue(trendingHistory);
    });

    when('getMarketHistory is called and price changes are calculated', async () => {
      result = await client.market.getMarketHistory(regionId, typeId);
      priceChanges = result
        .slice(1)
        .map((day: any, index: number) => day.average - result[index].average);
    });

    then('the client shall return data that reveals an upward trend with a total increase of 0.4', () => {
      expect(result.length).toBe(5);
      expect(priceChanges.every((change: any) => change > 0)).toBe(true); // Upward trend
      expect(result[result.length - 1].average).toBeGreaterThan(
        result[0].average,
      );

      // Calculate trend strength
      const totalChange = result[result.length - 1].average - result[0].average;
      expect(totalChange).toBeCloseTo(0.4, 2); // 10% increase over 5 days
    });
  });

  test('WHEN getCharacterOrders is called, the client shall return active market orders', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('the ESI character orders endpoint is available for an authenticated character', () => {
      const expectedOrders = [
        TestDataFactory.createCharacterMarketOrder({
          order_id: 5000000001,
          type_id: 34,
          region_id: 10000002,
          location_id: 60003760,
          range: 'region',
          volume_total: 1000000,
          volume_remain: 750000,
          min_volume: 1,
          price: 4.5,
          is_buy_order: true,
          duration: 90,
          issued: '2024-01-15T12:00:00Z',
          state: 'open',
        }),
      ];

      jest
        .spyOn(client.market, 'getCharacterOrders')
        .mockResolvedValue(expectedOrders);
    });

    when('getCharacterOrders is called with a valid character ID', async () => {
      result = await client.market.getCharacterOrders(characterId);
    });

    then('the client shall return an array of orders with state equal to open', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result[0]).toHaveProperty('order_id');
      expect(result[0]).toHaveProperty('type_id');
      expect(result[0]).toHaveProperty('price');
      expect(result[0]).toHaveProperty('state');
      expect(result[0].state).toBe('open');
    });
  });

  test('WHEN getCharacterOrderHistory is called, the client shall return completed and cancelled orders', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('the ESI character order history endpoint is available for an authenticated character', () => {
      const expectedHistory = [
        TestDataFactory.createCharacterOrderHistory({
          order_id: 5000000001,
          type_id: 34,
          region_id: 10000002,
          location_id: 60003760,
          range: 'region',
          volume_total: 1000000,
          volume_remain: 0,
          min_volume: 1,
          price: 4.5,
          is_buy_order: true,
          duration: 90,
          issued: '2024-01-10T12:00:00Z',
          state: 'closed',
        }),
      ];

      jest
        .spyOn(client.market, 'getCharacterOrderHistory')
        .mockResolvedValue(expectedHistory);
    });

    when('getCharacterOrderHistory is called with a valid character ID', async () => {
      result = await client.market.getCharacterOrderHistory(characterId);
    });

    then('the client shall return an array of orders with state closed, cancelled, or expired', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result[0]).toHaveProperty('order_id');
      expect(result[0]).toHaveProperty('state');
      expect(
        ['closed', 'cancelled', 'expired'].includes(result[0].state!),
      ).toBe(true);
      expect(result[0].volume_remain).toBeLessThanOrEqual(
        result[0].volume_total,
      );
    });
  });

  test('WHEN multiple market requests are made concurrently, the client shall complete all requests successfully', ({
    given,
    when,
    then,
  }) => {
    const regionIds = [10000002, 10000030, 10000043];
    const typeId = 34;
    let results: any;

    given('the ESI market orders endpoint is available for multiple regions', () => {
      const mockOrders = regionIds.map((regionId, index) => [
        TestDataFactory.createMarketOrder({
          order_id: 5000000001 + index,
          type_id: typeId,
          price: 4.5 + index * 0.1,
        }),
      ]);

      jest
        .spyOn(client.market, 'getMarketOrders')
        .mockImplementation(
          async (regionId: number) =>
            mockOrders[regionIds.indexOf(regionId)] || [],
        );
    });

    when('getMarketOrders is called concurrently for three region IDs', async () => {
      const promises = regionIds.map((regionId) =>
        client.market.getMarketOrders(regionId),
      );
      results = await Promise.all(promises);
    });

    then('the client shall return results for all three regions with correct prices', () => {
      expect(results).toHaveLength(3);
      results.forEach((result: any, index: number) => {
        expect(result).toBeInstanceOf(Array);
        expect(result[0].price).toBe(4.5 + index * 0.1);
      });
    });
  });

  test('WHEN a large market dataset is requested, the client shall handle it efficiently', ({ given, when, then }) => {
    const regionId = 10000002;
    const typeId = 34;
    let result: any;
    let startTime: number;
    let endTime: number;

    given('the ESI market orders endpoint returns 5000 orders for a region', () => {
      const largeOrderSet = Array.from({ length: 5000 }, (_, i) =>
        TestDataFactory.createMarketOrder({
          order_id: 5000000001 + i,
          type_id: typeId,
          price: 4.0 + Math.random() * 2,
          volume_remain: Math.floor(Math.random() * 1000000),
          is_buy_order: Math.random() > 0.5,
        }),
      );

      jest
        .spyOn(client.market, 'getMarketOrders')
        .mockResolvedValue(largeOrderSet);
    });

    when('getMarketOrders is called and the response contains 5000 orders', async () => {
      startTime = Date.now();
      result = await client.market.getMarketOrders(regionId);
      endTime = Date.now();
    });

    then('the client shall process all 5000 orders in under 1000 milliseconds', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result.length).toBe(5000);
      expect(endTime - startTime).toBeLessThan(1000);

      // Verify data integrity
      const buyOrders = result.filter((order: any) => order.is_buy_order);
      const sellOrders = result.filter((order: any) => !order.is_buy_order);
      expect(buyOrders.length + sellOrders.length).toBe(result.length);
    });
  });

  test('WHEN comprehensive market data is gathered, the client shall return prices, orders, and history', ({ given, when, then }) => {
    const regionId = 10000002;
    const typeId = 34;
    let prices: any;
    let orders: any;
    let history: any;

    given('the ESI market prices, orders, and history endpoints are all available', () => {
      const mockPrices = [
        TestDataFactory.createMarketPrice({
          type_id: typeId,
          average_price: 4.5,
        }),
      ];
      const mockOrders = [
        TestDataFactory.createMarketOrder({
          type_id: typeId,
          price: 4.45,
          is_buy_order: true,
        }),
        TestDataFactory.createMarketOrder({
          type_id: typeId,
          price: 4.55,
          is_buy_order: false,
        }),
      ];
      const mockHistory = [
        TestDataFactory.createMarketHistory({
          date: '2024-01-15',
          average: 4.5,
        }),
      ];

      jest
        .spyOn(client.market, 'getMarketPrices')
        .mockResolvedValue(mockPrices);
      jest
        .spyOn(client.market, 'getMarketOrders')
        .mockResolvedValue(mockOrders);
      jest
        .spyOn(client.market, 'getMarketHistory')
        .mockResolvedValue(mockHistory);
    });

    when('getMarketPrices, getMarketOrders, and getMarketHistory are called concurrently', async () => {
      [prices, orders, history] = await Promise.all([
        client.market.getMarketPrices(),
        client.market.getMarketOrders(regionId),
        client.market.getMarketHistory(regionId, typeId),
      ]);
    });

    then('the client shall return valid prices, orders, and history data for the requested type', () => {
      expect(prices).toBeInstanceOf(Array);
      expect(prices[0].type_id).toBe(typeId);

      expect(orders).toBeInstanceOf(Array);
      expect(orders[0].type_id).toBe(typeId);

      expect(history).toBeInstanceOf(Array);
      expect(history[0].date).toBe('2024-01-15');

      // Verify market analysis capabilities
      const currentPrice = prices.find(
        (p: any) => p.type_id === typeId,
      )?.average_price;
      const buyOrders = orders.filter((o: any) => o.is_buy_order);
      const sellOrders = orders.filter((o: any) => !o.is_buy_order);
      const bestBuyOrder =
        buyOrders.length > 0
          ? buyOrders.reduce((best: any, current: any) =>
              current.price > best.price ? current : best,
            )
          : null;
      const bestSellOrder =
        sellOrders.length > 0
          ? sellOrders.reduce((best: any, current: any) =>
              current.price < best.price ? current : best,
            )
          : null;

      expect(currentPrice).toBeDefined();
      expect(bestBuyOrder).toBeDefined();
      expect(bestSellOrder).toBeDefined();
    });
  });
});
"}
